import re,os,subprocess,collections
# collect exported funcs declared under internal/
decls=[]
for root,dirs,files in os.walk('internal'):
    for fn in files:
        if not fn.endswith('.go') or fn.endswith('_test.go'): continue
        p=os.path.join(root,fn)
        pkg=None
        for line in open(p,encoding='utf8',errors='ignore'):
            m=re.match(r'package (\w+)',line)
            if m: pkg=m.group(1)
            m=re.match(r'func ([A-Z]\w*)\(',line)
            if m: decls.append((pkg,m.group(1),p))
# count call sites pkg.Func(
counts=collections.Counter()
loc={}
allgo=subprocess.run(['bash','-c',"find . -name '*.go' -not -path './proto/gen/*'"],capture_output=True,text=True).stdout.split()
texts={f:open(f,encoding='utf8',errors='ignore').read() for f in allgo}
for pkg,fn,p in decls:
    pat=re.compile(r'\b'+pkg+r'\.'+fn+r'\(')
    n=0
    for f,t in texts.items():
        n+=len(pat.findall(t))
    counts[(pkg,fn)]=n
    loc[(pkg,fn)]=p
for (pkg,fn),n in counts.most_common(20):
    print(n,pkg+'.'+fn,loc[(pkg,fn)])
EOF

